<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateVersion\Infrastructure\Driver;

use Psr\Container\ContainerInterface;
use Override;
use Slim\Routing\RouteCollectorProxy;
use Civi\Lughauth\Features\Document\TemplateVersion\Infrastructure\Driver\Rest\TemplateVersionAllowController;
use Civi\Lughauth\Features\Document\TemplateVersion\Infrastructure\Driver\Rest\TemplateVersionListController;
use Civi\Lughauth\Features\Document\TemplateVersion\Infrastructure\Driver\Rest\TemplateVersionCreateController;
use Civi\Lughauth\Features\Document\TemplateVersion\Infrastructure\Driver\Rest\TemplateVersionRetrieveController;
use Civi\Lughauth\Features\Document\TemplateVersion\Infrastructure\Driver\Rest\TemplateVersionUpdateController;
use Civi\Lughauth\Features\Document\TemplateVersion\Infrastructure\Driver\Rest\TemplateVersionDeleteController;
use Civi\Lughauth\Shared\Security\Rbac\Handler;
use Civi\Lughauth\Shared\Infrastructure\MicroPlugin;
use Civi\Lughauth\Shared\Security\SecurityPlugin;
use Civi\Lughauth\Shared\Infrastructure\StartupProcessor;
use Civi\Lughauth\Shared\Event\EventListenersRegistrarInterface;
use Civi\Lughauth\Features\Document\TemplateVersion\Application\Service\Visibility\TemplateVersionRestrictFilterToVisibility;
use Civi\Lughauth\Features\Document\TemplateVersion\Application\Policy\Filter\TenantAccessible;
use Civi\Lughauth\Features\Document\TemplateVersion\Infrastructure\Driven\TemplateVersionCommandRepositoryAdapter;
use Civi\Lughauth\Features\Document\TemplateVersion\Infrastructure\Driven\TemplateVersionQueryRepositoryAdapter;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\Gateway\TemplateVersionQueryRepositoryGateway;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\Gateway\TemplateVersionCommandRepositoryGateway;

class TemplateVersionPlugin extends MicroPlugin
{
    #[Override]
    public function registerServiceDefinition(array $def): array
    {
        $def[TemplateVersionQueryRepositoryGateway::class] = \DI\autowire(TemplateVersionQueryRepositoryAdapter::class);
        $def[TemplateVersionCommandRepositoryGateway::class] = \DI\autowire(TemplateVersionCommandRepositoryAdapter::class);
        return $def;
    }
    #[Override]
    public function registerRoutes(RouteCollectorProxy $collector): void
    {
        $collector->group('/api/document/template-versions', [$this, 'setRoutesForTemplateVersion']);
        $collector->group('/api/me/acl/document/template-versions', [$this, 'setRoutesForTemplateVersionAcl']);
    }
    #[Override]
    public function registerEvents(EventListenersRegistrarInterface $listener): void
    {
        $listener->registerListener(TemplateVersionRestrictFilterToVisibility::class, TenantAccessible::class);
    }
    #[Override]
    public function registerStartup(StartupProcessor $processor): void
    {
        $processor->register(function (ContainerInterface $container) {
            $handler = $container->get(Handler::class);
            $handler->registerResourceAction("template-version", "list", "READ");
            $handler->registerResourceAction("template-version", "create", "WRITE");
            $handler->registerResourceAction("template-version", "retrieve", "READ");
            $handler->registerResourceAction("template-version", "update", "WRITE");
            $handler->registerResourceAction("template-version", "delete", "WRITE");

            $handler->registerResourceAttribute("template-version", "template", "MANAGE");
            $handler->registerResourceAttribute("template-version", "locale", "MANAGE");
            $handler->registerResourceAttribute("template-version", "subject", "MANAGE");
            $handler->registerResourceAttribute("template-version", "contentHtml", "MANAGE");
            $handler->registerResourceAttribute("template-version", "contentText", "MANAGE");
            $handler->registerResourceAttribute("template-version", "version", "MANAGE");
        }, StartupProcessor::before(SecurityPlugin::STARTUP_ORDER));
    }
    public function setRoutesForTemplateVersionAcl(RouteCollectorProxy $templateVersionGroup): void
    {
        $templateVersionGroup->get('', [TemplateVersionAllowController::class, 'genericAllow']);
        $templateVersionGroup->get('/{uid}', [TemplateVersionAllowController::class, 'contextualAllow']);
    }
    public function setRoutesForTemplateVersion(RouteCollectorProxy $templateVersionGroup): void
    {
        $templateVersionGroup->get('', [TemplateVersionListController::class, 'list']);
        $templateVersionGroup->post('', [TemplateVersionCreateController::class, 'create']);
        $templateVersionGroup->get('/{uid}', [TemplateVersionRetrieveController::class, 'retrieve']);
        $templateVersionGroup->put('/{uid}', [TemplateVersionUpdateController::class, 'update']);
        $templateVersionGroup->delete('/{uid}', [TemplateVersionDeleteController::class, 'delete']);
        $templateVersionGroup->delete('', [TemplateVersionDeleteController::class, 'deleteAllForQuery']);
        $templateVersionGroup->get('/~/delete-status/{uid}', [TemplateVersionDeleteController::class, 'checkDeleteAllForQueryStatus']);
    }
}
